PREBUILT_TOPICS['heaven'] = PREBUILT_TOPICS['heaven and eternal life'];
PREBUILT_TOPICS['trinity'] = PREBUILT_TOPICS['the trinity'];
PREBUILT_TOPICS['second coming'] = PREBUILT_TOPICS['the second coming'];
PREBUILT_TOPICS['return of christ'] = PREBUILT_TOPICS['the second coming'];
PREBUILT_TOPICS['repent'] = PREBUILT_TOPICS['repentance'];
PREBUILT_TOPICS['repenting'] = PREBUILT_TOPICS['repentance'];
PREBUILT_TOPICS['god\'s love'] = PREBUILT_TOPICS['love of god'];

export function findPrebuiltTopic(query: string): TopicStudyResult | null {
  const cleanKey = query.trim().toLowerCase();
  if (PREBUILT_TOPICS[cleanKey]) {
    return PREBUILT_TOPICS[cleanKey];
  }
  // Strip common prefixes
  const stripped = cleanKey.replace(/^(the|about|study on|biblical|on)\s+/, '');
  if (PREBUILT_TOPICS[stripped]) {
    return PREBUILT_TOPICS[stripped];
  }
  return null;
}
